const LIVE = window.VENDOR_DESK || null;
const apiUrl = path => `${LIVE.base}/${path}?t=${encodeURIComponent(LIVE.token)}`;
const SESSION_ENDED = 'Your session has ended. Please reload the page.';
const blank = v => ({ criteria: [], knockouts: [], red_flags: [], web_findings: [], questions: [], form: {}, ...v });

// Live rows carry the raw form keys; show them with plain labels.
const FORM_LABELS = { offering: 'What they supply', directors: 'Owners', certifications: 'Certificates', cert_expiry: 'Certificate dates',
  capacity: 'Monthly capacity', key_clients: 'Main clients', payment_terms: 'Payment terms', related_party_details: 'Related to anyone at EBM?',
  litigation_details: 'Any court cases or bans?', phone: 'Phone' };
function plainForm(form) {
  const out = {};
  for (const [k, val] of Object.entries(form || {})) if (val && FORM_LABELS[k]) out[FORM_LABELS[k]] = val;
  return out;
}

async function load() {
  state.demo = !LIVE;
  if (state.demo) {
    state.vendors = SAMPLE.map(v => blank({ ...v }));
  } else {
    try {
      // A plain GET with the pass in the link: no custom headers, so no CORS preflight.
      const res = await fetch(apiUrl('vendor-desk/vendors'));
      if (res.status === 401) throw new Error(SESSION_ENDED);
      if (!res.ok) throw new Error('The server replied with an error (' + res.status + ').');
      state.vendors = ((await res.json()).vendors || []).map(v => blank({ ...v, form: plainForm(v.form) }));
    } catch (e) {
      app.innerHTML = `<h1>We couldn't load the suppliers</h1><p class="lead">${esc(e.message)}</p>`;
      return;
    }
  }
  // The approver email links to the page with ?vendor=ID; n8n passes it in as LIVE.open.
  const wanted = (LIVE && LIVE.open) || decodeURIComponent(location.hash.slice(1));
  state.vendors.some(v => v.vendor_id === wanted) ? go('review', wanted) : go('home');
}

async function confirmDecision() {
  const v = state.vendors.find(x => x.vendor_id === state.id);
  const decision = state.choice || ADVICE_TO_CHOICE[v.recommendation];
  const note = ($('#note')?.value || '').trim();
  const notify = $('#notify')?.checked ?? true;
  const err = $('#err');
  if (decision === 'info_requested' && note.replace(/[•\s]/g, '').length === 0) { err.textContent = 'Please write what you need from them.'; return; }
  if (decision === 'approved' && v.blocked && note.length < 20) { err.textContent = 'Please write who gave permission and why. We need this on record.'; return; }
  const reviewer = store.get('name', '');
  if (!reviewer) { openSettings('Please add your name first. It is saved with your decision.'); return; }

  const btn = $('[data-confirm]');
  btn.disabled = true;
  try {
    if (!state.demo) {
      // Form-encoded body: a "simple" request that a sandboxed page can send without a preflight.
      const res = await fetch(apiUrl('vendor-desk/decision'), {
        method: 'POST',
        body: new URLSearchParams({ payload: JSON.stringify({ vendor_id: v.vendor_id, decision, note, reviewer, notify }) }),
      });
      if (res.status === 401) throw new Error(SESSION_ENDED);
      const out = await res.json().catch(() => ({}));
      if (!res.ok || out.ok === false) throw new Error(out.error || 'the server replied with an error');
    }
    Object.assign(v, { status: decision, reviewer, decided_at: new Date().toISOString(), _reopen: false,
      reviewer_note: v.blocked && decision === 'approved' ? '[Exception] ' + note : note });
    const next = waiting()[0];
    toast(`Done. ${v.company_name}: ${STATUS[decision].toLowerCase()}.${next ? ' Here is the next one.' : ''}`);
    next ? go('review', next.vendor_id) : go('home');
  } catch (e) {
    err.textContent = 'This was not saved: ' + e.message + '. Please try again.';
    btn.disabled = false;
  }
}

